/* ---------- CONFIG: put your construction photo here ----------
   Paste a data: URI (remote image URLs are blocked on hosted pages). Leave '' to use the built-in site illustration. */
const BG_PHOTO='data:image/jpeg;base64,';

const PROFS=['Site Engineer','Store Keeper','Project Auditor'];
/* Suite link: each role opens its own dashboard after login. */
const ROUTES={'Site Engineer':'/supervisor/','Store Keeper':'/storekeeper/','Project Auditor':'/auditor/'};
const DESC={'Site Engineer':'Report building progress with a stage, description and site photo.','Store Keeper':'Record material stock and check usage against expected figures.','Project Auditor':'Review progress reports and material discrepancy warnings.'};
const TABS={progress:'Report Building Progress',material:'Record Material Stock',reports:'View Reports'};
const ACCESS={'Site Engineer':['progress','reports'],'Store Keeper':['material','reports'],'Project Auditor':['reports']};
const STAGES=['Site clearing & excavation','Foundation','Plinth beam','Columns & structure','Slab / roofing','Brickwork','Plastering','Electrical & plumbing','Flooring & finishing','Painting & handover'];
const TOL=0.05; // 5% tolerance on expected usage
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- helpers ---------- */
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k));return v??d}catch(e){return d}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){return false}};
const sha=async t=>{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')};
const emailOk=e=>/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
const num=v=>v===''||v==null?NaN:Number(v);
const fmt=n=>Math.round(n*100)/100;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
let users=[],session=null,progress=load('bp_progress',[]),materials=load('bp_materials',[]),tab=null,fresh=null;

/* loading state on a button while an action runs (minimum visible time so feedback is noticeable) */
async function withLoading(btn,fn,min=650){btn.classList.add('loading');btn.disabled=true;try{const[r]=await Promise.all([fn(),sleep(RM?0:min)]);return r}finally{btn.classList.remove('loading');btn.disabled=false}}
function flashDone(btn,label){const h=btn.innerHTML;btn.innerHTML='✓ '+label;btn.classList.add('done');setTimeout(()=>{btn.innerHTML=h;btn.classList.remove('done')},1800)}
function animateNumber(el,to,dur=800){const from=el._v||0,int=Number.isInteger(to)&&Number.isInteger(from);el._v=to;cancelAnimationFrame(el._r);
 if(RM||from===to){el.textContent=fmt(to);return}
 const t0=performance.now(),step=t=>{const k=Math.min(1,(t-t0)/dur),v=from+(to-from)*(1-Math.pow(1-k,3));el.textContent=int?Math.round(v):fmt(v);if(k<1)el._r=requestAnimationFrame(step)};el._r=requestAnimationFrame(step)}
function runCounters(){document.querySelectorAll('[data-count]').forEach(el=>{el._v=0;animateNumber(el,+el.dataset.count,900)})}
function toast(msg,type='ok',title=''){const t=document.createElement('div');t.className='toast '+type;
 t.innerHTML=`<span class="ti">${type==='warn'?'!':'✓'}</span><div>${title?`<b>${esc(title)}</b>`:''}<span class="m">${esc(msg)}</span></div><button aria-label="Dismiss">×</button>`;
 $('#toasts').appendChild(t);requestAnimationFrame(()=>requestAnimationFrame(()=>t.classList.add('in')));
 const kill=()=>{t.classList.remove('in');setTimeout(()=>t.remove(),350)};t.querySelector('button').onclick=kill;setTimeout(kill,type==='warn'?7000:4500)}
/* validation feedback: message + red field state */
function setErr(k,m){const p=$('#e-'+k);if(p)p.textContent=m||'';const el=$('#'+k);if(el&&el.tagName!=='FORM'){(el.closest('.drop')||el).classList.toggle('invalid',!!m)}return!!m}
const clearInv=e=>{const t=e.target;if(!t.id)return;const h=t.closest('.drop')||t;if(h.classList&&h.classList.contains('invalid')){h.classList.remove('invalid');const p=$('#e-'+t.id);if(p)p.textContent=''}};
addEventListener('input',clearInv,true);addEventListener('change',clearInv,true);
const shake=()=>{const el=$('#dlg .sw');if(!el)return;el.classList.remove('shake');void el.offsetWidth;el.classList.add('shake')};

/* ---------- background (illustration stand-in; BG_PHOTO overrides it) ---------- */
function drawBg(){
 const bg=$('#bg');
 if(BG_PHOTO){bg.style.backgroundImage='url("'+BG_PHOTO+'")';return}
 const u=24,ox=600,oy=70,P=(x,y,z)=>[ox+(x-y)*.866*u,oy+(x+y)*.5*u-z*u*.62],pt=a=>a.map(p=>p.map(n=>n.toFixed(1)).join(',')).join(' ');
 let s=7;const r=()=>(s=(s*16807)%2147483647)/2147483647,list=[];
 for(let i=0;i<14;i++)for(let j=0;j<14;j++){if(r()<.12)continue;list.push({i,j,h:1.5+r()*5.5+(Math.abs(i-j)<3?r()*3:0),hl:r()>.9})}
 list.sort((a,b)=>(a.i+a.j)-(b.i+b.j));let out='';
 for(const b of list){const x=b.i*3.6,y=b.j*3.6,w=2.6,h=b.h;
  const L=pt([P(x,y+w,0),P(x+w,y+w,0),P(x+w,y+w,h),P(x,y+w,h)]),R=pt([P(x+w,y,0),P(x+w,y+w,0),P(x+w,y+w,h),P(x+w,y,h)]),T=pt([P(x,y,h),P(x+w,y,h),P(x+w,y+w,h),P(x,y+w,h)]);
  out+=b.hl?`<g stroke="#E6F007" stroke-width="1.6"><polygon points="${L}" fill="rgba(230,240,7,.12)"/><polygon points="${R}" fill="rgba(230,240,7,.07)"/><polygon points="${T}" fill="rgba(230,240,7,.18)"/></g>`
  :`<polygon points="${L}" fill="#363e4b"/><polygon points="${R}" fill="#262d38"/><polygon points="${T}" fill="#4d576a"/>`}
 out+=`<g stroke="#7c879b" stroke-width="2.2" fill="none" opacity=".85"><path d="M250 760V230M250 230L120 262M250 230L470 190M250 230V196L470 190M250 196L120 262M440 192V250"/><path d="M180 748L250 300M320 748L250 300" stroke-width="1.2" opacity=".6"/></g>`;
 bg.innerHTML=`<svg viewBox="0 0 1200 760" preserveAspectRatio="xMidYMid slice" focusable="false">${out}</svg>`;
}
drawBg();

/* ---------- scroll: parallax, progress, header state, reveals ---------- */
let tick=false;
function onScroll(){if(tick)return;tick=true;requestAnimationFrame(()=>{tick=false;const y=scrollY,d=document.documentElement,m=d.scrollHeight-innerHeight;
 d.style.setProperty('--py',RM?0:Math.min(y*.08,70));d.style.setProperty('--sp',m>0?y/m:0);$('header').classList.toggle('scrolled',y>12)})}
addEventListener('scroll',onScroll,{passive:true});onScroll();
let io=null;
function observeReveals(){io&&io.disconnect();const els=document.querySelectorAll('.rvs,.steps');
 if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('in'));return}
 io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.15});els.forEach(e=>io.observe(e))}
$('#logo').onclick=e=>{e.preventDefault();scrollTo({top:0,behavior:RM?'auto':'smooth'})};
$('#links').onclick=e=>{const a=e.target.closest('a[data-go]');if(!a)return;e.preventDefault();const t=document.getElementById(a.dataset.go);t&&t.scrollIntoView({behavior:RM?'auto':'smooth'})};

/* ---------- nav ---------- */
function toggleMenu(force){const m=$('#umm'),b=$('#umb');if(!m)return;const o=force===undefined?!m.classList.contains('open'):force;m.classList.toggle('open',o);b.setAttribute('aria-expanded',o)}
document.addEventListener('click',e=>{if(!e.target.closest('.um'))toggleMenu(false)});
function renderNav(){
 const nr=$('#navRight'),links=$('#links');
 if(session){
  links.innerHTML='';
  nr.innerHTML=`<div class="um"><button class="chip" id="umb" aria-haspopup="menu" aria-expanded="false" aria-controls="umm"><span class="av">${esc(session.name.trim()[0].toUpperCase())}</span><span class="nm">${esc(session.name)}</span><svg width="12" height="8" viewBox="0 0 12 8" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M1 1l5 5 5-5"/></svg></button>
   <div class="menu" id="umm" role="menu"><div class="mh"><b>${esc(session.name)}</b><span><span class="badge">${esc(session.profession)}</span></span><small>${esc(session.email)}</small><small>Authenticated account</small></div><button class="mi" role="menuitem" id="logout">Log out</button></div></div>`;
  $('#umb').onclick=e=>{e.stopPropagation();toggleMenu()};
  $('#logout').onclick=()=>{session=null;fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'}).finally(()=>{localStorage.removeItem('bp_session');location.assign('/')})};
 }else{
  links.innerHTML='<a href="#roles" data-go="roles">Roles</a><a href="#how" data-go="how">How it works</a>';
  nr.innerHTML='<button class="btn btn-nav" id="openLogin">Login</button><button class="btn btn-nav btn-y" id="openSignup">Sign Up</button>';
  $('#openLogin').onclick=()=>openModal('login');$('#openSignup').onclick=()=>openModal('signup');
 }
}
function render(){renderNav();session?renderDash():renderLanding();observeReveals()}

/* ---------- landing ---------- */
function renderLanding(){
 const bars=[['Foundation',100],['Columns & structure',72],['Slab / roofing',38]];
 $('#main').innerHTML=`<section class="hero">
  <div>
   <div class="eyebrow rv" style="--d:0">VERIFY. AUDIT. CLEAR.</div>
   <h1><span class="ln" style="--i:0"><span style="--i:0">Verified progress</span></span><span class="ln"><span style="--i:1">on every site,</span></span><span class="ln"><span class="hl" style="--i:2">before you pay.</span></span></h1>
   <p class="lead rv" style="--d:7">Site Engineers report progress with photos, Store Keepers record material stock, and Project Auditors review reports and discrepancy warnings, all in one place.</p>
   <div class="cta rv" style="--d:9"><button class="btn btn-y btn-lg" id="cta1">Get Started <span class="ar" aria-hidden="true">→</span></button><small>Free demo · runs in your browser</small></div>
  </div>
  <aside class="card site rv" style="--d:6" aria-label="Sample site status">
   <div class="cap"><span>SAMPLE SITE STATUS</span><em>Illustrative data</em></div>
   ${bars.map((b,i)=>`<div class="srow"><div><span>${b[0]}</span><b>${b[1]}%</b></div><div class="bar" style="margin:0 0 12px"><i style="--w:${b[1]}%;--i:${i}"></i></div></div>`).join('')}
   <div class="warn sflag"><span class="wi">!</span><div><b>Cement · discrepancy</b><p class="meta">Expected 24 bags used, 18 reported. Flagged for review.</p></div></div>
  </aside>
 </section>
 <section class="sec" id="roles"><div class="eyebrow">ROLES</div><h2>Three roles. One verified record.</h2>
  <div class="roles">${PROFS.map((p,i)=>`<button class="card role rvs" style="--i:${i}" data-p="${p}"><span class="n">0${i+1}</span><h3>${p}</h3><p>${DESC[p]}</p><span class="go">Login as ${p} <span class="ar">→</span></span></button>`).join('')}</div></section>
 <section class="sec" id="how"><div class="eyebrow">HOW IT WORKS</div><h2>From site photo to audit trail</h2>
  <div class="steps">${[['Report progress','The Site Engineer submits the construction stage, a description and a building photo.'],['Record stock','The Store Keeper logs opening, received and closing stock. Expected usage is calculated automatically.'],['Review & flag','The Project Auditor reviews reports and any material discrepancies the system flagged.']].map((s,i)=>`<div class="step" data-n="${i+1}"><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></section>`;
 $('#cta1').onclick=()=>openModal('signup');
 document.querySelectorAll('.role').forEach(b=>b.onclick=()=>openModal('login',b.dataset.p));
}

/* ---------- dashboard ---------- */
function renderDash(){
 const allowed=ACCESS[session.profession];if(!allowed.includes(tab))tab=allowed[0];fresh=null;
 $('#main').innerHTML=`<section class="welcome"><span class="eyebrow" style="--k:0">DEMO SESSION</span>
  <h1 style="--k:1">Welcome, <em>${esc(session.name)}</em></h1>
  <p class="wrole" style="--k:2"><span class="badge">${esc(session.profession)}</span><span>${DESC[session.profession]}</span></p>
  <p class="meta" style="--k:3">Demo sign-in: accounts exist only in this browser. This is not real authentication.</p></section>
  <div class="tabs" role="tablist" aria-label="Dashboard sections">${allowed.map(t=>`<button class="tab" role="tab" data-t="${t}" aria-selected="${t===tab}">${TABS[t]}</button>`).join('')}</div>
  <section class="card" id="panel" role="tabpanel"></section>`;
 document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{tab=b.dataset.t;showTab()});showTab();
}
function showTab(){
 document.querySelectorAll('.tab').forEach(b=>b.setAttribute('aria-selected',b.dataset.t===tab));
 const p=$('#panel');p.classList.remove('panel-in');void p.offsetWidth;p.classList.add('panel-in');
 ({progress:panelProgress,material:panelMaterial,reports:panelReports})[tab]();
}

/* progress form */
function panelProgress(){
 $('#panel').innerHTML=`<div class="ph"><h2>Report Building Progress</h2><p class="meta">Submit the current construction stage with a photo of the building.</p></div>
 <form id="pf" novalidate>
  <label for="stage">Construction stage</label><select class="inp" id="stage"><option value="">Select stage…</option>${STAGES.map(s=>`<option>${s}</option>`).join('')}</select><p class="err" id="e-stage"></p>
  <div class="tracker" id="trk" aria-hidden="true">${STAGES.map((s,i)=>`<i style="--i:${i}"></i>`).join('')}</div><p class="meta" id="trkl" style="margin-top:8px">Select a stage to see where it sits in the build sequence.</p>
  <label for="desc">Description</label><textarea class="inp" id="desc" placeholder="What work was completed? Location, quantities, notes…"></textarea><p class="err" id="e-desc"></p>
  <label for="photo">Building photo</label>
  <label class="drop" for="photo"><input id="photo" type="file" accept="image/*"><span class="ic" id="dic"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 16V4m0 0l-4 4m4-4l4 4M4 16v3a1 1 0 001 1h14a1 1 0 001-1v-3"/></svg></span><img id="prev" alt="Selected photo preview" class="hidden"><span id="dtxt">Choose a building photo (JPG, PNG)</span></label><p class="err" id="e-photo"></p>
  <button class="btn btn-y formbtn">Submit progress report</button></form>`;
 $('#stage').onchange=e=>{const i=STAGES.indexOf(e.target.value);[...$('#trk').children].forEach((x,k)=>x.classList.toggle('on',i>=0&&k<=i));
  $('#trkl').textContent=i<0?'Select a stage to see where it sits in the build sequence.':`Stage ${i+1} of ${STAGES.length} · ${STAGES[i]} · ${Math.round((i+1)/STAGES.length*100)}% of the build sequence`};
 $('#photo').onchange=e=>{const f=e.target.files[0],p=$('#prev');
  if(f&&f.type.startsWith('image/')){p.src=URL.createObjectURL(f);p.classList.remove('hidden');$('#dic').classList.add('hidden');$('#dtxt').textContent=f.name}
  else{p.classList.add('hidden');$('#dic').classList.remove('hidden');$('#dtxt').textContent=f?'Not an image. Choose a JPG or PNG.':'Choose a building photo (JPG, PNG)'}};
 $('#pf').onsubmit=async e=>{e.preventDefault();
  const stage=$('#stage').value,desc=$('#desc').value.trim(),f=$('#photo').files[0];let bad=false;
  bad=setErr('stage',stage?'':'Choose a construction stage.')||bad;
  bad=setErr('desc',desc.length>=10?'':'Enter a description (at least 10 characters).')||bad;
  bad=setErr('photo',!f?'Add a building photo.':!f.type.startsWith('image/')?'File must be an image.':f.size>10*1048576?'Photo must be under 10 MB.':'')||bad;
  if(bad)return;
  const btn=$('#pf .btn-y');
  const ok=await withLoading(btn,async()=>{const img=await shrink(f);progress.unshift({id:Date.now(),stage,desc,img,by:session.name,role:session.profession,at:new Date().toLocaleString()});
   if(!save('bp_progress',progress)){progress.shift();return false}return true},800);
  if(!ok){setErr('photo','Browser storage is full. Clear demo data in View Reports and retry.');return}
  flashDone(btn,'Report submitted');toast(`${stage} progress report saved with photo. See it under View Reports.`,'ok','Progress submitted');
  e.target.reset();$('#prev').classList.add('hidden');$('#dic').classList.remove('hidden');$('#dtxt').textContent='Choose a building photo (JPG, PNG)';[...$('#trk').children].forEach(x=>x.classList.remove('on'));$('#trkl').textContent='Select a stage to see where it sits in the build sequence.';
 };
}
function shrink(file){return new Promise(res=>{const im=new Image(),u=URL.createObjectURL(file);im.onload=()=>{const m=900,k=Math.min(1,m/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.72))};im.onerror=()=>res('');im.src=u})}

/* material form */
function calc(o,r,c,u){const exp=o+r-c,diff=u-exp,tol=Math.max(exp*TOL,0);return{exp:fmt(exp),diff:fmt(diff),flag:Math.abs(diff)>tol+1e-9}}
function warnText(m){return m.diff<0?`${Math.abs(m.diff)} less used than the stock movement shows. Possible loss, diversion or counting error.`:`${m.diff} more reported than the stock movement supports. Possible recording error or missing delivery.`}
function panelMaterial(){
 $('#panel').innerHTML=`<div class="ph"><h2>Record Material Stock</h2><p class="meta">Expected usage = opening stock + received − closing stock. Differences over ${TOL*100}% are flagged.</p></div>
 <form id="mf" novalidate>
  <label for="mat">Material (with unit)</label><input class="inp" id="mat" placeholder="e.g. Cement (bags)"><p class="err" id="e-mat"></p>
  <div class="grid2"><div><label for="op">Opening stock</label><input class="inp" id="op" type="number" min="0" step="any" inputmode="decimal"><p class="err" id="e-op"></p></div>
  <div><label for="rc">Received quantity</label><input class="inp" id="rc" type="number" min="0" step="any" inputmode="decimal"><p class="err" id="e-rc"></p></div>
  <div><label for="cl">Closing stock</label><input class="inp" id="cl" type="number" min="0" step="any" inputmode="decimal"><p class="err" id="e-cl"></p></div>
  <div><label for="us">Reported usage</label><input class="inp" id="us" type="number" min="0" step="any" inputmode="decimal"><p class="err" id="e-us"></p></div></div>
  <div class="calcbox" id="cb" data-s="idle" aria-live="polite">
   <div class="eq"><span id="q1">–</span><i>+</i><span id="q2">–</span><i>−</i><span id="q3">–</span><i>=</i><strong id="qx">–</strong></div>
   <p class="meta">Expected usage (opening + received − closing)</p>
   <div class="cmp"><div><span>Expected</span><div class="bar"><i id="bE"></i></div><b id="vE">–</b></div><div><span>Reported</span><div class="bar"><i id="bR"></i></div><b id="vR">–</b></div></div>
   <div class="status" id="st">Enter opening, received and closing stock to calculate expected usage.</div></div>
  <button class="btn btn-y formbtn">Submit stock record</button></form>`;
 ['op','rc','cl','us'].forEach(i=>$('#'+i).oninput=updCalc);
 $('#mf').onsubmit=async e=>{e.preventDefault();let bad=false;const v={};
  const mat=$('#mat').value.trim();bad=setErr('mat',mat?'':'Enter the material name.')||bad;
  [['op','Opening stock'],['rc','Received quantity'],['cl','Closing stock'],['us','Reported usage']].forEach(([k,n])=>{v[k]=num($('#'+k).value);bad=setErr(k,isNaN(v[k])?n+' is required.':v[k]<0?'Cannot be negative.':'')||bad});
  if(bad)return;
  if(v.op+v.rc-v.cl<0){setErr('cl','Closing stock cannot exceed opening + received.');return}
  const c=calc(v.op,v.rc,v.cl,v.us),btn=$('#mf .btn-y');
  await withLoading(btn,async()=>{materials.unshift({id:Date.now(),mat,open:v.op,recv:v.rc,close:v.cl,used:v.us,exp:c.exp,diff:c.diff,flag:c.flag,by:session.name,role:session.profession,at:new Date().toLocaleString()});save('bp_materials',materials)},700);
  flashDone(btn,c.flag?'Saved with warning':'Record saved');
  c.flag?toast(`${mat}: expected ${c.exp}, reported ${v.us}. Flagged in View Reports.`,'warn','Discrepancy flagged'):toast(`${mat} record saved. Reported usage is within tolerance.`,'ok','Stock recorded');
  e.target.reset();updCalc();
 };
}
function updCalc(){
 const g=i=>num($('#'+i).value),o=g('op'),r=g('rc'),c=g('cl'),u=g('us'),cb=$('#cb'),st=$('#st'),qx=$('#qx');
 const sh=(id,v)=>$('#'+id).textContent=isNaN(v)?'–':fmt(v),bar=(id,p)=>$('#'+id).style.width=Math.max(0,Math.min(100,p))+'%';
 sh('q1',o);sh('q2',r);sh('q3',c);sh('vR',u);
 if([o,r,c].some(isNaN)){cb.dataset.s='idle';qx.textContent='–';qx._v=0;sh('vE',NaN);bar('bE',0);bar('bR',0);st.textContent='Enter opening, received and closing stock to calculate expected usage.';return}
 const exp=o+r-c;
 if(exp<0){cb.dataset.s='err';qx.textContent='–';qx._v=0;sh('vE',NaN);bar('bE',0);bar('bR',0);st.textContent='Closing stock is higher than opening + received, so expected usage would be negative. Check the figures.';return}
 animateNumber(qx,fmt(exp),600);sh('vE',exp);
 if(isNaN(u)){cb.dataset.s='calc';bar('bE',100);bar('bR',0);st.textContent=`Expected usage is ${fmt(exp)}. Enter reported usage to compare.`;return}
 const res=calc(o,r,c,u),max=Math.max(exp,u,1e-9);bar('bE',exp/max*100);bar('bR',u/max*100);
 cb.dataset.s=res.flag?'bad':'ok';
 const pct=exp>0?Math.round(Math.abs(res.diff)/exp*100):null;
 st.textContent=res.flag?`Discrepancy: reported ${fmt(u)} vs expected ${fmt(exp)} (${res.diff>0?'+':''}${res.diff}${pct!==null?', '+pct+'%':''}). ${warnText(res)}`:`Within tolerance (±${fmt(exp*TOL)}). Reported usage matches the stock movement.`;
}

/* reports */
function panelReports(){
 const w=materials.filter(m=>m.flag),idx=progress.length?STAGES.indexOf(progress[0].stage):-1,pctS=idx>=0?Math.round((idx+1)/STAGES.length*100):0;
 $('#panel').innerHTML=`<div class="ph"><h2>View Reports</h2><p class="meta">All submitted records and discrepancy warnings in this browser.</p></div>
 <div class="stats"><div class="stat"><strong data-count="${progress.length}">0</strong><span>Progress reports</span></div><div class="stat"><strong data-count="${materials.length}">0</strong><span>Stock records</span></div><div class="stat ${w.length?'bad':''}"><strong data-count="${w.length}">0</strong><span>Warnings</span></div></div>
 <div class="lat"><div><span>${idx>=0?`Latest reported stage: <b>${esc(STAGES[idx])}</b>`:'No stage reported yet'}</span><b>${pctS}%</b></div><div class="bar"><i style="--w:${pctS}%"></i></div></div>
 <h3 class="sub">Warnings</h3>
 ${w.length?w.map((m,i)=>`<div class="warn stag" style="--i:${i}"><span class="wi">!</span><div><b>${esc(m.mat)}</b> · expected ${m.exp}, reported ${m.used}<p>${warnText(m)}</p><div class="meta">${esc(m.by)} (${esc(m.role)}) · ${esc(m.at)}</div></div></div>`).join(''):'<p class="meta">No discrepancies flagged.</p>'}
 <h3 class="sub">Building progress</h3>
 ${progress.length?progress.map((p,i)=>`<div class="rec stag" style="--i:${i}">${p.img?`<div class="thumb"><img src="${p.img}" alt="Site photo: ${esc(p.stage)}"></div>`:''}<div><strong>${esc(p.stage)}</strong><div>${esc(p.desc)}</div><div class="meta">${esc(p.by)} (${esc(p.role)}) · ${esc(p.at)}</div></div></div>`).join(''):'<p class="meta">No progress reports yet.</p>'}
 <h3 class="sub">Material stock</h3>
 ${materials.length?`<div class="tablewrap"><table><thead><tr><th>Material</th><th>Opening</th><th>Received</th><th>Closing</th><th>Reported</th><th>Expected</th><th>Status</th></tr></thead><tbody>${materials.map(m=>`<tr><td>${esc(m.mat)}<div class="meta">${esc(m.by)} · ${esc(m.at)}</div></td><td>${m.open}</td><td>${m.recv}</td><td>${m.close}</td><td>${m.used}</td><td>${m.exp}</td><td><span class="pill ${m.flag?'r':'g'}">${m.flag?'FLAGGED':'OK'}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="meta">No stock records yet.</p>'}
 ${progress.length||materials.length?'<button class="btn btn-sm" id="clr" style="margin-top:26px">Clear demo data</button>':''}`;
 const c=$('#clr');if(c)c.onclick=()=>{if(confirm('Delete all demo reports in this browser?')){progress=[];materials=[];save('bp_progress',[]);save('bp_materials',[]);showTab();toast('All demo reports were removed from this browser.','ok','Data cleared')}};
 runCounters();
}

/* ---------- modal: login / signup ---------- */
let lastFocus=null;
function openModal(kind,prof){lastFocus=document.activeElement;toggleMenu(false);kind==='login'?loginForm(prof,'first'):signupForm('first');$('#modal').classList.add('open');document.body.classList.add('lock');
 setTimeout(()=>{const f=$('#dlg').querySelector('input,select');f&&f.focus({preventScroll:true})},80)}
function closeModal(){$('#modal').classList.remove('open');document.body.classList.remove('lock');lastFocus&&lastFocus.focus&&lastFocus.focus()}
$('#modal').addEventListener('mousedown',e=>{if(e.target.id==='modal')closeModal()});
addEventListener('keydown',e=>{const open=$('#modal').classList.contains('open');
 if(e.key==='Escape'){open?closeModal():toggleMenu(false)}
 if(e.key==='Tab'&&open){const f=[...$('#dlg').querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!f.length)return;const a=f[0],z=f[f.length-1];
  if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});
const pwField=(id,label,ac)=>`<label for="${id}">${label}</label><div class="pw"><input class="inp" id="${id}" type="password" autocomplete="${ac}"><button type="button" data-show="${id}" aria-label="Show password">Show</button></div>`;
function wireShow(){document.querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>{const i=$('#'+b.dataset.show),h=i.type==='password';i.type=h?'text':'password';b.textContent=h?'Hide':'Show';b.setAttribute('aria-label',(h?'Hide':'Show')+' password')})}
function startSession(u,how){session={name:u.name,email:u.email,profession:u.profession};localStorage.removeItem('bp_session');if(ROUTES[session.profession]){location.assign(ROUTES[session.profession]);return}tab=null;fresh=how;closeModal();render();scrollTo({top:0});
 toast(`${how==='signup'?'Account created':'Sign-in successful'} as ${u.profession}.`,'ok','Welcome, '+u.name.split(' ')[0])}

function loginForm(prof,dir){
 $('#dlg').innerHTML=`<div class="sw ${dir==='l'?'l':dir==='first'?'first':''}"><button class="x" aria-label="Close" id="cx">×</button><h2 id="dlgTitle">Login</h2><p class="meta">Sign in with the role assigned to your account.</p>
 <form id="lf" novalidate>
  <label for="lp">Profession</label><select class="inp" id="lp">${PROFS.map(p=>`<option>${p}</option>`).join('')}</select>
  <label for="le">Email Address</label><input class="inp" id="le" type="email" autocomplete="email" placeholder="name@company.com"><p class="err" id="e-le"></p>
  ${pwField('lw','Password','current-password')}<p class="err" id="e-lw"></p><p class="err" id="e-lf" role="alert"></p>
  <button class="btn btn-y" style="width:100%;margin-top:22px;height:50px">Login</button></form>
  <p class="meta" style="margin-top:18px">No account yet? <button class="link" id="toS">Sign Up</button></p>
  <p class="meta" style="margin-top:4px">Your account and assigned role are stored securely in PostgreSQL.</p></div>`;
 if(prof)$('#lp').value=prof;
 $('#cx').onclick=closeModal;$('#toS').onclick=()=>{signupForm('r');$('#dlg input').focus({preventScroll:true})};wireShow();
 $('#lf').onsubmit=async e=>{e.preventDefault();const p=$('#lp').value,em=$('#le').value.trim().toLowerCase(),pw=$('#lw').value;
  let bad=setErr('le',!em?'Enter your email address.':emailOk(em)?'':'Enter a valid email address.');bad=setErr('lw',pw?'':'Enter your password.')||bad;setErr('lf','');
  if(bad){shake();return}
  try {const result=await withLoading($('#lf .btn-y'),()=>authApi('/api/auth/login',{email:em,password:pw,profession:p}),200);startSession(result.user,'login');}
  catch(err){setErr('lf',err.message);shake()}
 };
}

function signupForm(dir){
 let otp=null,verifiedEmail=null;
 $('#dlg').innerHTML=`<div class="sw ${dir==='l'?'l':dir==='first'?'first':''}"><button class="x" aria-label="Close" id="cx">×</button><h2 id="dlgTitle">Sign Up</h2><p class="meta">Create an account with a permanently assigned role.</p>
 <form id="sf" novalidate>
  <label for="sn">Full Name</label><input class="inp" id="sn" autocomplete="name"><p class="err" id="e-sn"></p>
  <label for="signupProfession">Profession</label><select class="inp" id="signupProfession" name="profession" required><option value="" disabled selected>Select your profession</option><option value="Site Engineer">Site Supervisor</option><option value="Store Keeper">Store Keeper</option><option value="Project Auditor">Project Auditor</option></select><p class="err" id="e-signupProfession"></p>
  <label for="se">Email Address</label><div class="with-btn"><input class="inp" id="se" type="email" autocomplete="email" placeholder="name@company.com"><button type="button" class="btn btn-sm" id="vb" style="height:auto;min-width:112px">Verify Email</button></div><p class="err" id="e-se"></p><div id="demoNote"></div>
  <label for="so">OTP</label><input class="inp" id="so" inputmode="numeric" maxlength="6" placeholder="6-digit code" autocomplete="one-time-code" disabled><p class="err" id="e-so"></p><p class="ok" id="ok-so"></p>
  <div id="auditorInvite" style="display:none"><label for="inviteCode">Auditor invitation code</label><input class="inp" id="inviteCode" type="password" autocomplete="off"><p class="meta">Auditor accounts require approval.</p></div>${pwField('sw','Password (min. 8 characters)','new-password')}<div class="meter" id="pm" data-s="0" aria-hidden="true"><i></i><i></i><i></i><i></i></div><p class="meta" id="pml" style="margin-top:4px;font-size:12px"></p><p class="err" id="e-sw"></p>
  <label for="sc">Confirm Password</label><input class="inp" id="sc" type="password" autocomplete="new-password"><p class="err" id="e-sc"></p><p class="ok" id="ok-sc"></p>
  <button class="btn btn-y" style="width:100%;margin-top:22px;height:50px">Sign Up</button></form>
  <p class="meta" style="margin-top:18px">Already registered? <button class="link" id="toL">Login</button></p></div>`;
 $('#cx').onclick=closeModal;$('#toL').onclick=()=>{loginForm(null,'l');$('#dlg input,#dlg select').focus({preventScroll:true})};wireShow();$('#signupProfession').addEventListener('change',()=>{$('#auditorInvite').style.display=$('#signupProfession').value==='Project Auditor'?'block':'none'});
 const reset=()=>{otp=null;verifiedEmail=null;$('#so').disabled=true;$('#so').value='';$('#ok-so').textContent='';$('#demoNote').innerHTML='';$('#vb').textContent='Verify Email'};
 $('#se').addEventListener('input',()=>{if(otp&&$('#se').value.trim().toLowerCase()!==verifiedEmail)reset()});
 $('#vb').onclick=async()=>{const em=$('#se').value.trim().toLowerCase();
  if(setErr('se',!em?'Enter your email address first.':emailOk(em)?'':'Enter a valid email address.'))return;
  try{const result=await withLoading($('#vb'),()=>authApi('/api/auth/send-otp',{email:em}),200);
    otp='SERVER_VERIFIED';verifiedEmail=em;$('#so').disabled=false;$('#so').focus();$('#vb').textContent='Resend code';
    $('#demoNote').innerHTML=result.dev_otp?`<div class="notice"><b>Local development verification code:</b> <b class="code">${esc(result.dev_otp)}</b>. For production, configure SMTP.</div>`:'<div class="notice">A verification code has been sent to your email.</div>';
  }catch(err){setErr('se',err.message)}
 };
 $('#so').addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'');const v=e.target.value;$('#ok-so').textContent='';
  if(v.length===6&&otp){$('#ok-so').textContent='Code entered; it will be checked by the server on sign up.'}});
 const pw=$('#sw'),cf=$('#sc'),chk=()=>{$('#ok-sc').textContent=cf.value&&cf.value===pw.value?'✓ Passwords match':''};
 pw.addEventListener('input',()=>{const v=pw.value;let s=0;if(v.length>=8)s++;if(/[a-z]/.test(v)&&/[A-Z]/.test(v))s++;if(/\d/.test(v))s++;if(/[^A-Za-z0-9]/.test(v)||v.length>=12)s++;if(!v)s=0;
  $('#pm').dataset.s=s;$('#pml').textContent=v?['','Weak','Fair','Good','Strong'][s]+' password':'';chk()});
 cf.addEventListener('input',chk);
 $('#sf').onsubmit=async e=>{e.preventDefault();
  const n=$('#sn').value.trim(),p=$('#signupProfession').value,em=$('#se').value.trim().toLowerCase(),o=$('#so').value.trim(),pv=pw.value,cv=cf.value;let bad=false;
  bad=setErr('sn',n.length>=2?'':'Enter your full name.')||bad;
  bad=setErr('signupProfession',p?'':'Select your profession.')||bad;
  bad=setErr('se',!em?'Email address is required.':!emailOk(em)?'Enter a valid email address.':'')||bad;
  bad=setErr('so',!otp||verifiedEmail!==em?'Click Verify Email first to get a demo code.':!/^\d{6}$/.test(o)?'Enter the 6-digit code.':'')||bad;
  bad=setErr('sw',pv.length>=8?'':'Password must be at least 8 characters.')||bad;
  bad=setErr('sc',!cv?'Confirm your password.':cv!==pv?'Passwords do not match.':'')||bad;
  if(bad){shake();const f=$('#sf .invalid');f&&f.focus({preventScroll:false});return}
  try {const result=await withLoading($('#sf .btn-y'),()=>authApi('/api/auth/signup',{name:n,email:em,password:pv,profession:p,otp:o,auditor_invite_code:$('#inviteCode').value}),200);startSession(result.user,'signup');}
  catch(err){setErr('se',err.message);shake()}
 };
}

async function authApi(url,body){const resp=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)});const data=await resp.json().catch(()=>({}));if(!resp.ok){const detail=data.detail;throw new Error(typeof detail==='string'?detail:'Request failed ('+resp.status+')')}return data}
(async()=>{try{const r=await fetch('/api/auth/me',{credentials:'same-origin'});if(r.ok){const v=await r.json();session=v.user;if(ROUTES[session.profession]){location.replace(ROUTES[session.profession]);return}}}catch(e){}render()})();
